#include "UI/ParameterPanel.h"
#include <QFormLayout>
#include <QLineEdit>
namespace myvocal { ParameterPanel::ParameterPanel(Project*p,QWidget*par):QWidget(par),m_project(p){auto*l=new QFormLayout(this);m_lyric=new QLineEdit(this);m_pitch=new QSpinBox(this);m_pitch->setRange(0,127);m_velocity=new QSpinBox(this);m_velocity->setRange(1,127);l->addRow("Lyric",m_lyric);l->addRow("Note",m_pitch);l->addRow("Velocity",m_velocity);connect(m_lyric,&QLineEdit::editingFinished,this,&ParameterPanel::commit);connect(m_pitch,qOverload<int>(&QSpinBox::valueChanged),this,[this]{commit();});connect(m_velocity,qOverload<int>(&QSpinBox::valueChanged),this,[this]{commit();});}void ParameterPanel::setSelectedNote(qint64 id){m_id=id;for(auto&t:m_project->tracks())if(auto*n=t.findNote(id)){m_lyric->setText(n->getLyric());m_pitch->setValue(n->getMidiNote());m_velocity->setValue(n->getVelocity());return;}}void ParameterPanel::commit(){if(m_id<0)return;for(auto&t:m_project->tracks())if(auto*n=t.findNote(m_id)){n->setLyric(m_lyric->text());n->setMidiNote(m_pitch->value());n->setVelocity(m_velocity->value());return;}} }
